import { createHash } from 'node:crypto'

/**
 * Activation token hashing (Admin Portal plan, Section 4). The raw
 * token is 32 random bytes, base64url-encoded, generated by the admin
 * portal server. Only this SHA-256 hex digest is ever stored, in
 * activation_tokens.token_hash. The admin portal implements the exact
 * same digest; the two must never drift.
 */
export function hashActivationToken(rawToken: string): string {
  return createHash('sha256').update(rawToken, 'utf8').digest('hex')
}
